/* Cosmic Night Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="cosmic-night-light"] {
  --background: rgb(244, 244, 252);
  --foreground: rgb(42, 41, 75);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(42, 41, 75);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(42, 41, 75);
  --primary: rgb(110, 85, 207);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(229, 224, 254);
  --secondary-foreground: rgb(73, 63, 125);
  --muted: rgb(241, 241, 248);
  --muted-foreground: rgb(107, 107, 139);
  --accent: rgb(215, 229, 255);
  --accent-foreground: rgb(42, 41, 75);
  --destructive: rgb(255, 87, 114);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(224, 224, 238);
  --input: rgb(224, 224, 238);
  --ring: rgb(110, 85, 207);
  --chart-1: rgb(110, 85, 207);
  --chart-2: rgb(157, 139, 250);
  --chart-3: rgb(94, 96, 239);
  --chart-4: rgb(125, 119, 250);
  --chart-5: rgb(71, 63, 181);
  --radius: 0.5rem;
  --sidebar: rgb(241, 241, 248);
  --sidebar-foreground: rgb(42, 41, 75);
  --sidebar-primary: rgb(110, 85, 207);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(215, 229, 255);
  --sidebar-accent-foreground: rgb(42, 41, 75);
  --sidebar-border: rgb(224, 224, 238);
  --sidebar-ring: rgb(110, 85, 207);
  --font-sans: Inter, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: rgb(45, 45, 83);
  --shadow-opacity: 0.12;
  --shadow-blur: 10px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 10px 0px hsl(240 30% 25% / 0.06);
  --shadow-xs: 0px 4px 10px 0px hsl(240 30% 25% / 0.06);
  --shadow-sm:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 1px 2px -1px hsl(240 30% 25% / 0.12);
  --shadow:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 1px 2px -1px hsl(240 30% 25% / 0.12);
  --shadow-md:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 2px 4px -1px hsl(240 30% 25% / 0.12);
  --shadow-lg:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 4px 6px -1px hsl(240 30% 25% / 0.12);
  --shadow-xl:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 8px 10px -1px hsl(240 30% 25% / 0.12);
  --shadow-2xl: 0px 4px 10px 0px hsl(240 30% 25% / 0.3);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="cosmic-night-dark"] {
  --background: rgb(14, 14, 24);
  --foreground: rgb(226, 226, 248);
  --card: rgb(26, 26, 47);
  --card-foreground: rgb(226, 226, 248);
  --popover: rgb(26, 26, 47);
  --popover-foreground: rgb(226, 226, 248);
  --primary: rgb(165, 145, 255);
  --primary-foreground: rgb(14, 14, 24);
  --secondary: rgb(44, 42, 82);
  --secondary-foreground: rgb(197, 196, 253);
  --muted: rgb(34, 34, 67);
  --muted-foreground: rgb(161, 161, 195);
  --accent: rgb(49, 50, 96);
  --accent-foreground: rgb(226, 226, 248);
  --destructive: rgb(255, 87, 114);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(49, 49, 83);
  --input: rgb(49, 49, 83);
  --ring: rgb(165, 145, 255);
  --chart-1: rgb(165, 145, 255);
  --chart-2: rgb(122, 135, 201);
  --chart-3: rgb(103, 181, 245);
  --chart-4: rgb(73, 182, 171);
  --chart-5: rgb(252, 121, 196);
  --radius: 0.5rem;
  --sidebar: rgb(26, 26, 47);
  --sidebar-foreground: rgb(226, 226, 248);
  --sidebar-primary: rgb(165, 145, 255);
  --sidebar-primary-foreground: rgb(14, 14, 24);
  --sidebar-accent: rgb(49, 50, 96);
  --sidebar-accent-foreground: rgb(226, 226, 248);
  --sidebar-border: rgb(49, 49, 83);
  --sidebar-ring: rgb(165, 145, 255);
  --font-sans: Inter, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: rgb(45, 45, 83);
  --shadow-opacity: 0.12;
  --shadow-blur: 10px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 10px 0px hsl(240 30% 25% / 0.06);
  --shadow-xs: 0px 4px 10px 0px hsl(240 30% 25% / 0.06);
  --shadow-sm:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 1px 2px -1px hsl(240 30% 25% / 0.12);
  --shadow:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 1px 2px -1px hsl(240 30% 25% / 0.12);
  --shadow-md:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 2px 4px -1px hsl(240 30% 25% / 0.12);
  --shadow-lg:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 4px 6px -1px hsl(240 30% 25% / 0.12);
  --shadow-xl:
    0px 4px 10px 0px hsl(240 30% 25% / 0.12),
    0px 8px 10px -1px hsl(240 30% 25% / 0.12);
  --shadow-2xl: 0px 4px 10px 0px hsl(240 30% 25% / 0.3);
}
